CREATE TABLE IF NOT EXISTS aviation_contributor_invitations (id varchar PRIMARY KEY DEFAULT gen_random_uuid(), token_hash text NOT NULL UNIQUE, contributor_name text NOT NULL, contributor_email varchar NOT NULL, organization text, internal_note text, status text NOT NULL DEFAULT 'active', reusable_for_revisions boolean NOT NULL DEFAULT true, expires_at timestamp, opened_at timestamp, first_submission_at timestamp, revoked_at timestamp, created_by_user_id varchar REFERENCES users(id) ON DELETE SET NULL, created_at timestamp DEFAULT now(), updated_at timestamp DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_aviation_contributor_invite_status ON aviation_contributor_invitations(status, expires_at);
CREATE TABLE IF NOT EXISTS aviation_briefing_submissions (id varchar PRIMARY KEY DEFAULT gen_random_uuid(), invitation_id varchar NOT NULL UNIQUE REFERENCES aviation_contributor_invitations(id) ON DELETE CASCADE, contributor_name text NOT NULL, contributor_email varchar NOT NULL, contributor_title text, contributor_credentials text, contributor_organization text, contributor_bio text, contributor_profile_image_url text, contributor_links_json jsonb NOT NULL DEFAULT '{}'::jsonb, title text NOT NULL, description text NOT NULL, category text NOT NULL, video_provider text NOT NULL, video_url text NOT NULL, original_publication_url text, thumbnail_url text, video_duration_seconds integer, transcript text, content_outline text, intended_audience text, relevant_tool_ids_json jsonb NOT NULL DEFAULT '[]'::jsonb, additional_notes text, disclosures_json jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'draft', revision_request text, internal_review_notes text, review_checklist_json jsonb NOT NULL DEFAULT '{}'::jsonb, credentials_reviewed boolean NOT NULL DEFAULT false, aviation_review_recommended boolean NOT NULL DEFAULT false, aviation_review_completed boolean NOT NULL DEFAULT false, assigned_reviewer_user_id varchar REFERENCES users(id) ON DELETE SET NULL, agreement_accepted boolean NOT NULL DEFAULT false, agreement_version text, agreement_accepted_at timestamp, submitted_at timestamp, reviewed_at timestamp, approved_at timestamp, rejected_at timestamp, withdrawn_at timestamp, published_briefing_id varchar REFERENCES aviation_briefings(id) ON DELETE SET NULL, created_at timestamp DEFAULT now(), updated_at timestamp DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_aviation_submission_status ON aviation_briefing_submissions(status, created_at DESC); CREATE INDEX IF NOT EXISTS idx_aviation_submission_email ON aviation_briefing_submissions(contributor_email); CREATE INDEX IF NOT EXISTS idx_aviation_submission_category ON aviation_briefing_submissions(category); CREATE INDEX IF NOT EXISTS idx_aviation_submission_reviewer ON aviation_briefing_submissions(assigned_reviewer_user_id); CREATE INDEX IF NOT EXISTS idx_aviation_submission_briefing ON aviation_briefing_submissions(published_briefing_id);
